// Processar métricas e gerar alertas
const metricas = $input.all();
const alertas = [];
const dashboard = {};

// Processar cada métrica
for (const item of metricas) {
  const { metrica, valor, timestamp } = item.json;
  dashboard[metrica] = valor;

  // Verificar alertas
  switch (metrica) {
    case 'hitl_pendentes':
      if (valor > 5) {
        alertas.push({
          tipo: 'warning',
          metrica: metrica,
          valor: valor,
          limite: 5,
          mensagem: `${valor} solicitações HITL pendentes (limite: 5)`
        });
      }
      break;

    case 'tempo_resposta_medio':
      if (valor > 300) { // 5 minutos
        alertas.push({
          tipo: 'warning',
          metrica: metrica,
          valor: valor,
          limite: 300,
          mensagem: `Tempo médio de resposta: ${Math.round(valor)}s (limite: 300s)`
        });
      }
      break;

    case 'interacoes_periodo':
      if (valor > 100) {
        alertas.push({
          tipo: 'info',
          metrica: metrica,
          valor: valor,
          limite: 100,
          mensagem: `Alto volume de interações: ${valor} nos últimos 15min`
        });
      }
      break;
  }
}

// Calcular taxa de conversão (exemplo)
const visitas = dashboard.visitas_hoje || 0;
const interacoes = dashboard.interacoes_periodo || 1;
const taxa_conversao = (visitas / interacoes * 100).toFixed(2);

dashboard.taxa_conversao_estimada = taxa_conversao;
dashboard.timestamp = new Date().toISOString();
dashboard.alertas = alertas;

return {
  json: {
    dashboard: dashboard,
    alertas: alertas,
    necessita_notificacao: alertas.length > 0
  }
};

// Gerar relatório formatado
const dados = $input.first().json;

const relatorio = {
  periodo: 'Última hora',
  timestamp: dados.timestamp_relatorio,
  resumo: {
    total_interacoes: dados.total_interacoes || 0,
    clientes_unicos: dados.clientes_unicos || 0,
    tempo_resposta_medio: Math.round(dados.tempo_resposta_medio || 0),
    taxa_hitl: dados.total_interacoes > 0 ? 
      ((dados.interacoes_hitl / dados.total_interacoes) * 100).toFixed(1) : '0.0'
  },
  canais: {
    whatsapp: dados.interacoes_whatsapp || 0,
    email: dados.interacoes_email || 0
  },
  visitas: {
    agendadas: dados.visitas_agendadas || 0,
    realizadas: dados.visitas_realizadas || 0,
    canceladas: dados.visitas_canceladas || 0,
    taxa_realizacao: dados.visitas_agendadas > 0 ? 
      ((dados.visitas_realizadas / dados.visitas_agendadas) * 100).toFixed(1) : '0.0'
  },
  imoveis: {
    novos_cadastros: dados.imoveis_cadastrados || 0
  }
};

// Verificar se precisa enviar relatório (apenas se houver atividade significativa)
const enviar_relatorio = dados.total_interacoes > 10 || 
                        dados.visitas_agendadas > 0 || 
                        dados.imoveis_cadastrados > 0;

return {
  json: {
    relatorio: relatorio,
    enviar_relatorio: enviar_relatorio
  }
};
